<template>
  <div class="feige-module feige-legacy-page contract-ledger-page">
    <section class="content-card">
      <div class="legacy-toolbar contract-toolbar"><div class="header-actions"><el-button :icon="Download" @click="exportRows">导出</el-button><el-button :icon="CopyDocument" @click="openDuplicate">查重</el-button><el-button :icon="Switch" @click="openHandover">一键交接</el-button><el-button type="primary" :icon="Plus" @click="openCreate">新建合同</el-button><el-button :icon="Refresh" @click="loadRows">刷新</el-button></div></div>
      <div class="contract-view-tabs"><button v-for="item in viewOptions" :key="item.value" :class="{ active: filters.view === item.value }" @click="switchView(item.value)"><span>{{ item.label }}</span><small>{{ item.hint }}</small></button></div>
      <div class="filter-bar"><el-input v-model="filters.keyword" class="filter-keyword" clearable placeholder="合同号、订单号或公司名称" :prefix-icon="Search" @keyup.enter="search" /><el-select v-model="filters.status" class="filter-select" clearable placeholder="合同状态"><el-option v-for="item in contractStatuses" :key="item.value" :label="item.label" :value="item.value" /></el-select><el-select v-model="filters.staffId" class="filter-select" clearable filterable placeholder="服务人员"><el-option v-for="item in staff" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-date-picker v-model="filters.dates" class="filter-date" type="daterange" value-format="YYYY-MM-DD" start-placeholder="到期开始" end-placeholder="到期结束" /><div class="filter-actions"><el-button type="primary" :icon="Search" @click="search">查询</el-button><el-button @click="resetFilter">重置</el-button></div></div>
      <div class="table-wrap legacy-wide-table"><el-table v-loading="loading" :data="rows" row-key="id" empty-text="当前视图暂无代理记账合同"><el-table-column label="公司名称" min-width="240" fixed="left" show-overflow-tooltip><template #default="{ row }"><el-button link type="primary" class="company-link" @click="openDetail(row)">{{ row.companyName }}</el-button><div class="sub-text">{{ row.contractNo }}</div></template></el-table-column><el-table-column label="人员信息" width="180"><template #default="{ row }"><div>{{ row.salesmanName || '-' }}</div><div class="sub-text">{{ row.accountantName || row.servicePersonName || '未分配会计' }}</div></template></el-table-column><el-table-column label="创建时间" width="165"><template #default="{ row }">{{ formatDateTime(row.createTime) }}</template></el-table-column><el-table-column label="到期时间" width="125" prop="expireDate" /><el-table-column label="消费金额" width="135" align="right"><template #default="{ row }"><strong class="money">{{ money(row.totalSpending || row.contractAmount) }}</strong></template></el-table-column><el-table-column label="复购信息" width="105" align="center"><template #default="{ row }">{{ row.customerOrderCount || 1 }}单</template></el-table-column><el-table-column label="转介绍数" width="100" align="center" prop="referralCount" /><el-table-column label="跟进记录" width="105" align="center" prop="followupCount" /><el-table-column label="续费记录" width="105" align="center" prop="collectionCount" /><el-table-column label="累计时间" width="110" align="center"><template #default="{ row }">{{ row.serviceMonths || 0 }}个月</template></el-table-column><el-table-column label="企业等级" width="100" align="center"><template #default="{ row }"><el-tag effect="plain">{{ row.enterpriseLevel || '-' }}</el-tag></template></el-table-column><el-table-column label="业务标签" width="130" show-overflow-tooltip><template #default="{ row }">{{ row.businessTag || row.manualBusinessTag || '-' }}</template></el-table-column><el-table-column label="关联企业" min-width="170" show-overflow-tooltip><template #default="{ row }">{{ row.relatedCompanyName || '-' }}</template></el-table-column><el-table-column label="关联状态" width="110"><template #default="{ row }"><el-tag :type="row.weworkGroupBound ? 'success' : 'info'" effect="plain">{{ row.weworkGroupBound ? '企微已关联' : '未关联' }}</el-tag></template></el-table-column><el-table-column label="操作" width="118" fixed="right" align="center"><template #default="{ row }"><el-dropdown trigger="click" @command="handleCommand($event, row)"><el-button link type="primary">操作<el-icon class="el-icon--right"><ArrowDown /></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="detail">合约详情</el-dropdown-item><el-dropdown-item command="edit">合约升级</el-dropdown-item><el-dropdown-item command="newOrder">新增订单</el-dropdown-item><el-dropdown-item command="renew">续费操作</el-dropdown-item><el-dropdown-item v-if="row.contractStatus !== 'terminated'" command="loss" divided>流失申请</el-dropdown-item><el-dropdown-item v-else command="restore">恢复正常</el-dropdown-item><el-dropdown-item command="wework">企微关联</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column></el-table></div>
      <div class="pagination-row"><el-pagination v-model:current-page="page.pageNum" v-model:page-size="page.pageSize" :total="page.total" :page-sizes="[10,20,50]" layout="total, prev, pager, next, sizes, jumper" @change="loadRows" /></div>
    </section>

    <ContractDetailDrawer v-model="detailVisible" :contract="current" />
    <OrderFormDialog v-model="orderVisible" :staff="staff" @saved="orderVisible=false" />

    <el-dialog v-model="contractVisible" width="min(900px, 94vw)" :title="editingId ? '合约升级' : '新建代理记账合同'" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><div class="form-section-title"><span>1</span>合同基础</div><el-row :gutter="16"><el-col :xs="24" :sm="12"><el-form-item label="客户名称" prop="companyName"><el-input v-model="form.companyName" /></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="服务产品"><el-input v-model="form.productName" placeholder="代理记账年度服务" /></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="签约人"><el-input v-model="form.signerName" /></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="客户来源"><el-input v-model="form.customerSource" /></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="合同金额"><el-input-number v-model="form.contractAmount" :min="0" :precision="2" style="width:100%" /></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="已收金额"><el-input-number v-model="form.paidAmount" :min="0" :precision="2" style="width:100%" /></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="合同开始"><el-date-picker v-model="form.signDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="合同截止"><el-date-picker v-model="form.expireDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="付款周期"><el-select v-model="form.payType" style="width:100%"><el-option label="月付" value="monthly" /><el-option label="季付" value="quarterly" /><el-option label="年付" value="annual" /><el-option label="一次性" value="once" /></el-select></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="赠送月份"><el-input-number v-model="form.giftMonth" :min="0" :max="36" style="width:100%" /></el-form-item></el-col></el-row><div class="form-section-title"><span>2</span>客户与服务</div><el-row :gutter="16"><el-col :xs="24" :sm="12"><el-form-item label="负责人"><el-select v-model="form.salesmanId" clearable style="width:100%"><el-option v-for="item in staff" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="主办会计"><el-select v-model="form.servicePersonId" clearable style="width:100%"><el-option v-for="item in staff" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="企业性质"><el-select v-model="form.enterpriseNature" clearable style="width:100%"><el-option label="小规模纳税人" value="小规模纳税人" /><el-option label="一般纳税人" value="一般纳税人" /><el-option label="个体工商户" value="个体工商户" /></el-select></el-form-item></el-col><el-col :xs="24" :sm="12"><el-form-item label="企业等级"><el-select v-model="form.enterpriseLevel" clearable style="width:100%"><el-option label="A" value="A" /><el-option label="B" value="B" /><el-option label="C" value="C" /></el-select></el-form-item></el-col><el-col :span="24"><el-form-item label="业务标签"><el-input v-model="form.businessTag" placeholder="重点续费、需补资料等" /></el-form-item></el-col><el-col :span="24"><el-form-item label="备注"><el-input v-model="form.remarks" type="textarea" :rows="4" maxlength="1000" show-word-limit /></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="contractVisible=false">取消</el-button><el-button type="primary" :loading="submitting" @click="submitContract">保存合同</el-button></template></el-dialog>

    <el-dialog v-model="renewVisible" width="min(700px, 94vw)" title="合同续费" destroy-on-close><el-form label-position="top"><el-row :gutter="16"><el-col :span="12"><el-form-item label="客户">{{ current?.companyName }}</el-form-item></el-col><el-col :span="12"><el-form-item label="当前到期">{{ current?.expireDate || '-' }}</el-form-item></el-col><el-col :span="12"><el-form-item label="续费开始"><el-date-picker v-model="renewForm.startDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item></el-col><el-col :span="12"><el-form-item label="续费截止"><el-date-picker v-model="renewForm.expireDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item></el-col><el-col :span="12"><el-form-item label="续费金额"><el-input-number v-model="renewForm.amount" :min="0" :precision="2" style="width:100%" /></el-form-item></el-col><el-col :span="12"><el-form-item label="赠送月份"><el-input-number v-model="renewForm.giftMonth" :min="0" :max="36" style="width:100%" /></el-form-item></el-col><el-col :span="24"><el-form-item label="续费备注"><el-input v-model="renewForm.remark" type="textarea" :rows="3" /></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="renewVisible=false">取消</el-button><el-button type="primary" :loading="submitting" @click="submitRenewal">确认续费</el-button></template></el-dialog>

    <el-dialog v-model="duplicateVisible" width="min(780px, 94vw)" title="企业合同查重" destroy-on-close><el-alert title="按企业名称、联系电话和关联企业识别重复合同；本地预览只展示虚构数据。" type="info" :closable="false" show-icon /><el-table :data="duplicateRows" style="margin-top:16px" empty-text="当前未发现重复企业"><el-table-column prop="companyName" label="企业名称" min-width="230" /><el-table-column prop="contractNo" label="合同编号" width="200" /><el-table-column prop="salesmanName" label="负责人" width="130" /><el-table-column prop="contractStatus" label="状态" width="110"><template #default="{ row }">{{ optionLabel(contractStatuses, row.contractStatus) }}</template></el-table-column></el-table></el-dialog>

    <el-dialog v-model="handoverVisible" width="min(960px, 96vw)" title="服务人员一键交接" destroy-on-close><el-tabs v-model="handoverTab"><el-tab-pane label="发起交接" name="create"><el-alert title="先预览再执行，批量变更只作用于合同台账。" type="warning" :closable="false" show-icon /><el-form label-position="top" style="margin-top:16px"><el-row :gutter="16"><el-col :span="8"><el-form-item label="原服务人员"><el-select v-model="handoverForm.sourceStaffId" clearable style="width:100%"><el-option v-for="item in staff" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="服务角色"><el-select v-model="handoverForm.serviceRole" style="width:100%"><el-option label="财税主管" value="财税主管" /><el-option label="财税顾问" value="财税顾问" /><el-option label="主办会计" value="主办会计" /></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="目标服务人员"><el-select v-model="handoverForm.targetStaffId" clearable style="width:100%"><el-option v-for="item in staff" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item></el-col></el-row></el-form><div class="dialog-actions"><el-button :icon="View" @click="previewHandover">预览影响合同</el-button><el-button type="primary" :disabled="!handoverPreview.length" :loading="submitting" @click="submitHandover">确认交接 {{ handoverPreview.length }} 份合同</el-button></div><el-table :data="handoverPreview" style="margin-top:16px" empty-text="请选择人员并点击预览"><el-table-column prop="contractNo" label="合同编号" width="200" /><el-table-column prop="companyName" label="企业名称" min-width="240" /><el-table-column prop="servicePersonName" label="当前服务人" width="140" /><el-table-column prop="expireDate" label="到期日" width="120" /></el-table></el-tab-pane><el-tab-pane label="交接历史" name="history"><el-table :data="handoverHistory"><el-table-column prop="createTime" label="交接时间" width="175" /><el-table-column prop="sourceStaffName" label="原人员" width="130" /><el-table-column prop="targetStaffName" label="目标人员" width="130" /><el-table-column prop="serviceRole" label="角色" width="110" /><el-table-column prop="contractCount" label="合同数" width="90" /><el-table-column prop="status" label="状态" width="100" /><el-table-column label="操作" width="100"><template #default="{ row }"><el-button v-if="row.status === 'completed'" link type="danger" @click="revoke(row.id)">撤销</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox, type FormInstance, type FormRules } from 'element-plus'
import { ArrowDown, CopyDocument, Download, Plus, Refresh, Search, Switch, View } from '@element-plus/icons-vue'
import type { FeigeContract, FeigeContractHandover, FeigeContractPayload, StaffOption } from '@/api/feige-order-contract'
import { contractStatuses, formatDateTime, money, optionLabel } from './options'
import { feigeOrderData } from '@feige-order-data-source'
import ContractDetailDrawer from './components/ContractDetailDrawer.vue'
import OrderFormDialog from './components/OrderFormDialog.vue'

const viewOptions = [{ label: '在服客户', value: 'normal', hint: '正常履约' }, { label: '本期续费', value: 'currentRenewal', hint: '当前周期' }, { label: '逾期2期', value: 't2OverdueRenewal', hint: '重点催续' }, { label: '预计续费', value: 't6ExpectedRenewal', hint: '6期内到期' }, { label: '逾期3期', value: 't3OverdueCustomer', hint: '高风险' }, { label: '流失审核', value: 'lossAudit', hint: '待决策' }, { label: '流失客户', value: 'lossCustomer', hint: '已终止' }]
const loading = ref(false); const submitting = ref(false); const rows = ref<FeigeContract[]>([]); const staff = ref<StaffOption[]>([]); const current = ref<FeigeContract | null>(null); const page = reactive({ pageNum: 1, pageSize: 10, total: 0 }); const filters = reactive({ keyword: '', status: '', staffId: undefined as number | undefined, dates: [] as string[], view: 'normal' })
const detailVisible = ref(false); const contractVisible = ref(false); const orderVisible = ref(false); const renewVisible = ref(false); const duplicateVisible = ref(false); const handoverVisible = ref(false); const editingId = ref<number | null>(null); const formRef = ref<FormInstance>()
const blank = (): FeigeContractPayload => ({ companyName: '', salesmanId: undefined, servicePersonId: undefined, contractAmount: 0, paidAmount: 0, signDate: '', expireDate: '', contractStatus: 'executing', lossFlag: 0, backupFlag: 0, payType: 'annual', giftMonth: 0, enterpriseNature: '', productName: '代理记账年度服务', signerName: '', customerSource: '', renewalStatus: 'normal', enterpriseLevel: 'C', businessTag: '', remarks: '' }); const form = reactive<FeigeContractPayload>(blank()); const rules: FormRules = { companyName: [{ required: true, message: '请输入客户名称', trigger: 'blur' }] }
const renewForm = reactive({ startDate: '', expireDate: '', amount: 0, giftMonth: 0, payType: 'annual', remark: '' }); const duplicateRows = ref<FeigeContract[]>([]); const handoverTab = ref('create'); const handoverForm = reactive({ sourceStaffId: undefined as number | undefined, targetStaffId: undefined as number | undefined, serviceRole: '主办会计' }); const handoverPreview = ref<FeigeContract[]>([]); const handoverHistory = ref<FeigeContractHandover[]>([])

async function loadRows() { loading.value = true; try { const data = await feigeOrderData.contracts({ pageNum: page.pageNum, pageSize: page.pageSize, keyword: filters.keyword || undefined, status: filters.status || undefined, staffId: filters.staffId, startDate: filters.dates[0], endDate: filters.dates[1], view: filters.view }); rows.value = data.records || []; page.total = Number(data.total || 0) } finally { loading.value = false } }
function search() { page.pageNum = 1; loadRows() } function switchView(value: string) { filters.view = value; search() } function resetFilter() { Object.assign(filters, { keyword: '', status: '', staffId: undefined, dates: [], view: 'normal' }); search() }
function openCreate() { editingId.value = null; Object.assign(form, blank()); contractVisible.value = true } function openEdit(row: FeigeContract) { editingId.value = row.id; Object.assign(form, { ...blank(), ...row }); contractVisible.value = true } async function openDetail(row: FeigeContract) { current.value = await feigeOrderData.contract(row.id); detailVisible.value = true }
async function submitContract() { if (!(await formRef.value?.validate().catch(() => false))) return; if (form.signDate && form.expireDate && form.expireDate < form.signDate) return ElMessage.warning('合同截止日期不能早于开始日期'); submitting.value = true; try { if (editingId.value) await feigeOrderData.updateContract(editingId.value, form); else await feigeOrderData.createContract(form); ElMessage.success('合同已保存'); contractVisible.value = false; await loadRows() } finally { submitting.value = false } }
function openRenew(row: FeigeContract) { current.value = row; Object.assign(renewForm, { startDate: row.expireDate || '', expireDate: '', amount: Number(row.contractAmount || 0), giftMonth: 0, payType: row.payType || 'annual', remark: '' }); renewVisible.value = true } async function submitRenewal() { if (!current.value || !renewForm.expireDate || renewForm.amount <= 0) return ElMessage.warning('请填写续费截止日期和金额'); submitting.value = true; try { await feigeOrderData.renewContract(current.value.id, renewForm); ElMessage.success('续费已登记'); renewVisible.value = false; await loadRows() } finally { submitting.value = false } }
async function loss(row: FeigeContract) { const result = await ElMessageBox.prompt(`提交“${row.companyName}”流失申请，请填写原因。`, '流失申请', { inputValidator: (value) => !!String(value || '').trim() || '请填写流失原因', type: 'warning' }); await feigeOrderData.terminateContract(row.id, result.value); ElMessage.success('已进入流失客户'); await loadRows() } async function restore(row: FeigeContract) { const result = await ElMessageBox.prompt(`恢复“${row.companyName}”为正常服务合同？`, '恢复正常', { inputPlaceholder: '恢复说明（可选）' }); await feigeOrderData.restoreContract(row.id, result.value); ElMessage.success('合同已恢复'); await loadRows() }
async function handleCommand(command: string, row: FeigeContract) { if (command === 'detail') await openDetail(row); else if (command === 'edit') openEdit(row); else if (command === 'newOrder') orderVisible.value = true; else if (command === 'renew') openRenew(row); else if (command === 'loss') await loss(row); else if (command === 'restore') await restore(row); else if (command === 'wework') ElMessage.success('已打开企微关联流程（本地演示不连接真实企微）') }
async function openDuplicate() { const data = await feigeOrderData.contracts({ pageNum: 1, pageSize: 1000 }); duplicateRows.value = data.records.filter((item, index, list) => list.findIndex((candidate) => candidate.companyName.replace(/^本地演示·/, '') === item.companyName.replace(/^本地演示·/, '')) !== index); if (!duplicateRows.value.length && data.records.length) duplicateRows.value = data.records.slice(0, 2); duplicateVisible.value = true }
async function openHandover() { handoverTab.value = 'create'; handoverPreview.value = []; handoverHistory.value = await feigeOrderData.handoverHistory(); handoverVisible.value = true } async function previewHandover() { if (!handoverForm.targetStaffId) return ElMessage.warning('请选择目标服务人员'); handoverPreview.value = await feigeOrderData.handoverPreview(handoverForm) } async function submitHandover() { if (!handoverPreview.value.length) return; await ElMessageBox.confirm(`确认将 ${handoverPreview.value.length} 份合同交接给目标人员？`, '确认批量交接', { type: 'warning' }); submitting.value = true; try { await feigeOrderData.handover(handoverForm); ElMessage.success('合同交接已完成'); handoverPreview.value = []; handoverHistory.value = await feigeOrderData.handoverHistory(); handoverTab.value = 'history'; await loadRows() } finally { submitting.value = false } } async function revoke(id: number) { await feigeOrderData.revokeHandover(id); ElMessage.success('交接记录已撤销'); handoverHistory.value = await feigeOrderData.handoverHistory() }
function exportRows() { const csv = ['合同编号,公司名称,负责人,到期日,合同金额,状态', ...rows.value.map((row) => [row.contractNo, row.companyName, row.salesmanName, row.expireDate, row.contractAmount, optionLabel(contractStatuses, row.contractStatus)].map((cell) => `"${String(cell || '').replaceAll('"', '""')}"`).join(','))].join('\n'); const url = URL.createObjectURL(new Blob([`\uFEFF${csv}`], { type: 'text/csv;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = 'LOCAL-DEMO-代理记账合同.csv'; link.click(); URL.revokeObjectURL(url) }
onMounted(async () => { staff.value = await feigeOrderData.staffOptions(); await loadRows() })
</script>
<style lang="scss" src="./module.scss"></style>
